      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;
  int I, J;

  /* Create local restrict-qualified aliases to help the optimizer.
     All three 2D arrays are disjoint and use the same row-major layout. */
  DATA_TYPE (*restrict ex_)[ny]    = ex;
  DATA_TYPE (*restrict ey_)[ny]    = ey;
  DATA_TYPE (*restrict hz_)[ny]    = hz;
  DATA_TYPE *restrict fict_        = _fict_;

  /* Hoist scalar constants once. */
  const DATA_TYPE cey = SCALAR_VAL(0.5);
  const DATA_TYPE chz = SCALAR_VAL(0.7);

  /* Cached problem sizes for use inside the SCoP.  _PB_* are PolyBench
     “processed” sizes, potentially smaller than nx,ny,tmax when
     validating or using reduced domains. */
  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;
  const int tmax_ = _PB_TMAX;

  /* Tunable spatial tile sizes.  These improve cache locality by
     operating on TI x TJ sub-blocks of the 2D grid.  Edge tiles are
     handled explicitly via min() logic below. */
  const int TI = 32;
  const int TJ = 64;

#pragma scop

  for (t = 0; t < tmax_; t++)
    {
      /* Hoist _fict_[t] into a scalar: used for the entire ey boundary row. */
      const DATA_TYPE ft = fict_[t];

      /* 1) Boundary condition on ey at i = 0.
         Tiled in j to encourage good cache behavior and SIMD on the
         innermost unit-stride dimension. */
      for (J = 0; J < ny_; J += TJ)
        {
          int j_end = J + TJ;
          if (j_end > ny_) j_end = ny_;
          for (j = J; j < j_end; j++)
            ey_[0][j] = ft;
        }

      /* 2) Update ey for i in [1, nx_).  This is a 2D stencil that reads
            hz[i][j] and hz[i-1][j] and writes ey[i][j].  We block the
         i and j dimensions to increase data reuse in caches. */
      for (I = 1; I < nx_; I += TI)
        {
          int i_end = I + TI;
          if (i_end > nx_) i_end = nx_;

          for (J = 0; J < ny_; J += TJ)
            {
              int j_end = J + TJ;
              if (j_end > ny_) j_end = ny_;

              for (i = I; i < i_end; i++)
                {
                  /* j is unit-stride; GCC will typically vectorize this loop.
                     There are no loop-carried dependencies on ey_, hz_. */
                  for (j = J; j < j_end; j++)
                    ey_[i][j] = ey_[i][j]
                               - cey * (hz_[i][j] - hz_[i-1][j]);
                }
            }
        }

      /* 3) Update ex for j in [1, ny_).  Same tiling pattern as ey, but
         with the shifted j-range and horizontal finite difference. */
      for (I = 0; I < nx_; I += TI)
        {
          int i_end = I + TI;
          if (i_end > nx_) i_end = nx_;

          for (J = 1; J < ny_; J += TJ)
            {
              int j_end = J + TJ;
              if (j_end > ny_) j_end = ny_;

              for (i = I; i < i_end; i++)
                {
                  for (j = J; j < j_end; j++)
                    ex_[i][j] = ex_[i][j]
                               - cey * (hz_[i][j] - hz_[i][j-1]);
                }
            }
        }

      /* 4) Update hz on the interior domain [0, nx_-1) x [0, ny_-1).
         This uses the *new* ex and ey from steps (2–3) and the previous
         hz value.  Again we tile for improved locality. */
      for (I = 0; I < nx_ - 1; I += TI)
        {
          int i_end = I + TI;
          if (i_end > nx_ - 1) i_end = nx_ - 1;

          for (J = 0; J < ny_ - 1; J += TJ)
            {
              int j_end = J + TJ;
              if (j_end > ny_ - 1) j_end = ny_ - 1;

              for (i = I; i < i_end; i++)
                {
                  for (j = J; j < j_end; j++)
                    hz_[i][j] = hz_[i][j]
                               - chz * ((ex_[i][j+1] - ex_[i][j]) +
                                        (ey_[i+1][j] - ey_[i][j]));
                }
            }
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

