   - Use row pointers and restrict-qualified locals to reduce index arithmetic
     and help the compiler vectorize inner j-loops (unit-stride accesses).
*/
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t;

  /* Hoisted numeric constants: exactly the same values as SCALAR_VAL(0.5/0.7)
     used in the original loops, but loaded once outside the time loop. */
  const DATA_TYPE cey = SCALAR_VAL(0.5);
  const DATA_TYPE chz = SCALAR_VAL(0.7);

  /* Tunable tile sizes for spatial blocking.
     These values are chosen conservatively; they can be tuned for a
     particular machine, but must remain independent of nx, ny. */
  const int TI = 32;
  const int TJ = 64;

#pragma scop

  for (t = 0; t < _PB_TMAX; t++)
    {
      /* Hoist fictitious boundary value for this time step into a scalar. */
      const DATA_TYPE ft = _fict_[t];

      /* --------------------------------------------------------------------
       * 1) Ey boundary condition at i = 0:
       *    ey[0][j] = _fict_[t]  for all 0 <= j < NY.
       * ------------------------------------------------------------------*/
      {
        int j;
        DATA_TYPE *restrict ey0 = ey[0];
        for (j = 0; j < _PB_NY; j++)
          ey0[j] = ft;
      }

      /* --------------------------------------------------------------------
       * 2) Ex update on row i = 0, columns j >= 1:
       *    ex[0][j] = ex[0][j] - 0.5 * (hz[0][j] - hz[0][j-1]);
       *
       * This row is special because there is no ey-update at i = 0;
       * interior Ex/Ey updates for i >= 1 are handled in a fused, tiled loop
       * below. Keeping row 0 separate preserves the original update domain.
       * ------------------------------------------------------------------*/
      {
        int j;
        DATA_TYPE *restrict ex0 = ex[0];
        DATA_TYPE *restrict hz0 = hz[0];
        for (j = 1; j < _PB_NY; j++)
          ex0[j] = ex0[j] - cey * (hz0[j] - hz0[j-1]);
      }

      /* --------------------------------------------------------------------
       * 3) Fused interior E-field updates for i >= 1:
       *
       * Original code (separate passes):
       *   ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);        i in [1, NX), j in [0, NY)
       *   ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);        i in [0, NX), j in [1, NY)
       *
       * Here, for i >= 1 we update both ey and ex together:
       *
       *   - For j = 0: only ey is updated (ex has no j-1 neighbor).
       *   - For j >= 1: we update both ey[i][j] and ex[i][j], using the
       *     same hz[i][j] value once, improving cache and register reuse.
       *
       * These updates depend only on hz and on ex/ey at the same (i,j),
       * so fusing and reordering them is algebraically equivalent.
       *
       * Spatial blocking (tiling) over i and j improves data locality.
       * ------------------------------------------------------------------*/
      {
        int ii, jj;

        for (ii = 1; ii < _PB_NX; ii += TI)
        {
          int i_max = ii + TI;
          if (i_max > _PB_NX)
            i_max = _PB_NX;

          for (jj = 0; jj < _PB_NY; jj += TJ)
          {
            int j_max = jj + TJ;
            if (j_max > _PB_NY)
              j_max = _PB_NY;

            int i;
            for (i = ii; i < i_max; i++)
            {
              DATA_TYPE *restrict ex_i   = ex[i];
              DATA_TYPE *restrict ey_i   = ey[i];
              DATA_TYPE *restrict hz_i   = hz[i];
              DATA_TYPE *restrict hz_im1 = hz[i-1];

              /* Column j = 0: only ey update (original ey loop covers j=0). */
              if (jj == 0)
              {
                ey_i[0] = ey_i[0] - cey * (hz_i[0] - hz_im1[0]);
              }

              /* Columns j >= 1: fused ey and ex updates. */
              {
                int j;
                const int j_start = (jj == 0) ? 1 : jj;
                for (j = j_start; j < j_max; j++)
                {
                  const DATA_TYPE hz_ij = hz_i[j];

                  /* ey update: uses hz[i][j] and hz[i-1][j] */
                  ey_i[j] = ey_i[j] - cey * (hz_ij - hz_im1[j]);

                  /* ex update: uses hz[i][j] and hz[i][j-1] */
                  ex_i[j] = ex_i[j] - cey * (hz_ij - hz_i[j-1]);
                }
              }
            }
          }
        }
      }

      /* --------------------------------------------------------------------
       * 4) Hz update on interior points:
       *
       * Original code:
       *   for (i = 0; i < NX-1; i++)
       *     for (j = 0; j < NY-1; j++)
       *       hz[i][j] -= 0.7 * ( (ex[i][j+1] - ex[i][j])
       *                          + (ey[i+1][j] - ey[i][j]) );
       *
       * We preserve this computation exactly, but apply 2D tiling and use
       * row pointers to improve cache behavior and enable SIMD on j.
       * ------------------------------------------------------------------*/
      {
        int ii, jj;
        const int nxm1 = _PB_NX - 1;
        const int nym1 = _PB_NY - 1;

        for (ii = 0; ii < nxm1; ii += TI)
        {
          int i_max = ii + TI;
          if (i_max > nxm1)
            i_max = nxm1;

          for (jj = 0; jj < nym1; jj += TJ)
          {
            int j_max = jj + TJ;
            if (j_max > nym1)
              j_max = nym1;

            int i;
            for (i = ii; i < i_max; i++)
            {
              DATA_TYPE *restrict ex_i   = ex[i];
              DATA_TYPE *restrict ex_ip1 = ex[i+1];
              DATA_TYPE *restrict ey_i   = ey[i];
              DATA_TYPE *restrict ey_ip1 = ey[i+1];
              DATA_TYPE *restrict hz_i   = hz[i];

              int j;
              for (j = jj; j < j_max; j++)
              {
                const DATA_TYPE d_ex = ex_i[j+1] - ex_i[j];
                const DATA_TYPE d_ey = ey_ip1[j] - ey_i[j];

                hz_i[j] = hz_i[j] - chz * (d_ex + d_ey);
              }
            }
          }
        }
      }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
		  POLYBENCH_ARRAY(ex),
		  POLYBENCH_ARRAY(ey),
		  POLYBENCH_ARRAY(hz),
		  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
