static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny) __restrict,
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny) __restrict,
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny) __restrict,
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax) __restrict)
{
  int t, i, j;
  int ii, jj;

  /* Hoist scalar constants out of the loops. */
  const DATA_TYPE cey = SCALAR_VAL(0.5);
  const DATA_TYPE chz = SCALAR_VAL(0.7);

  /* Tunable spatial tile sizes (chosen for cache behavior). */
  const int ti = 32;
  const int tj = 64;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      /* Hoist _fict_[t] into a scalar to avoid redundant loads. */
      DATA_TYPE ft = _fict_[t];

      /* 1) Ey boundary condition on row i = 0.
         ey(0, j) = _fict_[t] for all j. */
      for (j = 0; j < _PB_NY; j++)
        ey[0][j] = ft;

      /* 2) Ex update on the first row (i = 0), for j >= 1.
         This corresponds to the i = 0 slice of the original ex-update loop. */
      for (j = 1; j < _PB_NY; j++)
        ex[0][j] = ex[0][j] - cey * (hz[0][j] - hz[0][j-1]);

      /* 3) Ey update on the first interior column (j = 0), for i >= 1.
         This corresponds to the j = 0 slice of the original ey-update loop. */
      for (i = 1; i < _PB_NX; i++)
        ey[i][0] = ey[i][0] - cey * (hz[i][0] - hz[i-1][0]);

      /* 4) Fused interior E-field update for i >= 1, j >= 1:
             - Update Ey using vertical differences of Hz.
             - Update Ex using horizontal differences of Hz.
         This fusion reduces Hz loads while preserving exact per-element
         expressions. The work is spatially tiled for better cache locality. */
      for (ii = 1; ii < _PB_NX; ii += ti)
      {
        int i_end = ii + ti;
        if (i_end > _PB_NX)
          i_end = _PB_NX;

        for (jj = 1; jj < _PB_NY; jj += tj)
        {
          int j_end = jj + tj;
          if (j_end > _PB_NY)
            j_end = _PB_NY;

          for (i = ii; i < i_end; i++)
          {
            /* j is the unit-stride dimension; hint the compiler that
               there are no loop-carried dependencies across j. */
#pragma GCC ivdep
            for (j = jj; j < j_end; j++)
            {
              DATA_TYPE hz_ij = hz[i][j];

              ey[i][j] = ey[i][j] - cey * (hz_ij - hz[i-1][j]);
              ex[i][j] = ex[i][j] - cey * (hz_ij - hz[i][j-1]);
            }
          }
        }
      }

      /* 5) Hz update over the interior region:
             0 <= i < NX-1, 0 <= j < NY-1.
         Uses newly updated Ex and Ey from this time step and the old Hz.
         Spatial tiling improves data locality for ex/ey/hz. */
      for (ii = 0; ii < _PB_NX - 1; ii += ti)
      {
        int i_end = ii + ti;
        if (i_end > _PB_NX - 1)
          i_end = _PB_NX - 1;

        for (jj = 0; jj < _PB_NY - 1; jj += tj)
        {
          int j_end = jj + tj;
          if (j_end > _PB_NY - 1)
            j_end = _PB_NY - 1;

          for (i = ii; i < i_end; i++)
          {
#pragma GCC ivdep
            for (j = jj; j < j_end; j++)
            {
              hz[i][j] = hz[i][j] - chz *
                         ( (ex[i][j+1] - ex[i][j]) +
                           (ey[i+1][j] - ey[i][j]) );
            }
          }
        }
      }
    }

#pragma endscop
