		    ey_[i][0] = ey_[i][0] - cey * (hz_[i][0] - hz_[i-1][0]);
		}

	      /* Columns j >= 1: update both Ey and Ex, reusing hz[i][j]. */
	      const int j_start = (jj == 0) ? 1 : jj;

	      for (i = ii; i < i_end; ++i)
		{
#pragma GCC ivdep
		  for (j = j_start; j < j_end; ++j)
		    {
		      const DATA_TYPE hz_ij = hz_[i][j];

		      ey_[i][j] = ey_[i][j] - cey * (hz_ij - hz_[i-1][j]);
		      ex_[i][j] = ex_[i][j] - cey * (hz_ij - hz_[i][j-1]);
		    }
		}
	    }
	}

      /* 4) Hz update over the interior domain.
       *
       *    Original:
       *      hz[i][j] = hz[i][j] - 0.7 * ( (ex[i][j+1]-ex[i][j])
       *                                   + (ey[i+1][j]-ey[i][j]) );
       *
       *    Uses newly updated Ex/Ey and old Hz; no cross-(i,j)
       *    dependences in Hz, so the spatial loops can be blocked
       *    and safely vectorized along j.
       */
      const int NXm1 = NX_ - 1;
      const int NYm1 = NY_ - 1;

      for (int ii = 0; ii < NXm1; ii += tile_i)
	{
	  const int i_end = (ii + tile_i < NXm1) ? (ii + tile_i) : NXm1;

	  for (int jj = 0; jj < NYm1; jj += tile_j)
	    {
	      const int j_end = (jj + tile_j < NYm1) ? (jj + tile_j) : NYm1;

	      for (i = ii; i < i_end; ++i)
		{
#pragma GCC ivdep
		  for (j = jj; j < j_end; ++j)
		    {
		      const DATA_TYPE d_ex = ex_[i][j+1] - ex_[i][j];
		      const DATA_TYPE d_ey = ey_[i+1][j] - ey_[i][j];
		      hz_[i][j] = hz_[i][j] - chz * (d_ex + d_ey);
		    }
		}
	    }
	}
    }

#pragma endscop
}


